// Parse the score JSON, build the persist SQL, and decide apply/park.
function q(s){ return String(s==null?'':s).replace(/'/g, "''"); }
const raw = $json.response || '';
let p; try { p = JSON.parse(raw); } catch(e){ const m = raw.match(/\{[\s\S]*\}/); p = m ? JSON.parse(m[0]) : { score: 0 }; }
const job = $('Get Jobs to Score').item.json;
const resume = $('Get Default Resume').first().json;
const score = Math.max(0, Math.min(100, Number(p.score) || 0));
const minApply = Number($env.SCORE_MIN_TO_APPLY || 70);
const apply = score >= minApply;
const breakdown = q(JSON.stringify({ skills_match: p.skills_match ?? null, experience_match: p.experience_match ?? null }));
const model = $env.OLLAMA_MODEL_REASONING || 'llama3.1:8b';
const query = `INSERT INTO app.job_scores (job_id, resume_id, score, breakdown, reasoning, model) VALUES ('${job.id}','${resume.id}',${score},'${breakdown}'::jsonb,'${q(p.reasoning)}','${q(model)}') ON CONFLICT (job_id, resume_id) DO UPDATE SET score = EXCLUDED.score, breakdown = EXCLUDED.breakdown, reasoning = EXCLUDED.reasoning; UPDATE app.jobs SET status = '${apply ? 'scored' : 'parked'}' WHERE id = '${job.id}';`;
return { json: { job_id: job.id, resume_id: resume.id, title: job.title, company: job.company_name, description: job.description, resume_text: resume.raw_text, score, apply, query } };

// Assemble the application package file + persist SQL.
const ps = $('Parse Score').item.json;
const tailored = $('Tailor Resume').item.json.response || '';
const cover = $('Cover Letter').item.json.response || '';
const md = `# Tailored Resume — ${ps.title} @ ${ps.company}

${tailored}

---

# Cover Letter

${cover}
`;
const path = `/data/storage/applications/${ps.job_id}.md`;
const query = `INSERT INTO app.applications (job_id, resume_id, tailored_resume_path, cover_letter_path, status) VALUES ('${ps.job_id}','${ps.resume_id}','${path}','${path}','ready') ON CONFLICT (job_id, resume_id) DO UPDATE SET tailored_resume_path = EXCLUDED.tailored_resume_path, cover_letter_path = EXCLUDED.cover_letter_path, status = 'ready'; UPDATE app.jobs SET status = 'ready' WHERE id = '${ps.job_id}';`;
return { json: { job_id: ps.job_id, path, query }, binary: { data: { data: Buffer.from(md).toString('base64'), fileName: `${ps.job_id}.md`, mimeType: 'text/markdown' } } };
